import{_ as s,o as t,c as a,a2 as i}from"./chunks/framework.CAKCj7G0.js";const h=JSON.parse('{"title":"2-5. Redux介绍","description":"","frontmatter":{},"headers":[],"relativePath":"DuOneClass/11.react(谢杰)/codestation前台/2-5. Redux介绍.md","filePath":"DuOneClass/11.react(谢杰)/codestation前台/2-5. Redux介绍.md"}'),r={name:"DuOneClass/11.react(谢杰)/codestation前台/2-5. Redux介绍.md"};function l(m,e,p,n,o,d){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="_2-5-redux介绍" tabindex="-1">2-5. Redux介绍 <a class="header-anchor" href="#_2-5-redux介绍" aria-label="Permalink to &quot;2-5. Redux介绍&quot;">​</a></h1><h1 id="react-redux-介绍" tabindex="-1"><em>React-redux</em> 介绍 <a class="header-anchor" href="#react-redux-介绍" aria-label="Permalink to &quot;*React-redux* 介绍&quot;">​</a></h1><ul><li>什么是状态管理</li><li><em>Redux</em> 的核心思想</li><li><em>React-redux</em> 介绍</li></ul><h2 id="什么是状态管理" tabindex="-1">什么是状态管理 <a class="header-anchor" href="#什么是状态管理" aria-label="Permalink to &quot;什么是状态管理&quot;">​</a></h2><p>所谓状态管理，指的是<strong>把组件之间需要共享的状态抽取出来，遵循特定的约定，统一来管理，让状态的变化可以预测</strong>。</p><p>组件之间通常会有一些共享的状态，在 <em>Vue</em> 或者 <em>React</em> 中我们一般会将这部分状态提升至公共父组件的 <em>props</em> 中，由父组件来统一管理共享的状态，状态的改变也是由父组件执行并向下传递。这样会导致两个问题:</p><ul><li>需要将共享的状态提升至公共的父组件，若无公共的父组件，往往需要自行构造</li><li>状态由父组件自上而下逐层传递，若组件层级过多，数据传递会变得很冗杂</li></ul><p><img src="https://s2.loli.net/2024/09/06/EaWBUdpjxGkoPb1.png" alt=""></p><p>此时，我们就需要一个统一的仓库来对组件状态进行管理，如下图：</p><p><img src="https://s2.loli.net/2024/09/06/dUvBFo8uA3EDhsW.png" alt=""></p><h2 id="redux-的核心思想" tabindex="-1"><em>Redux</em> 的核心思想 <a class="header-anchor" href="#redux-的核心思想" aria-label="Permalink to &quot;*Redux* 的核心思想&quot;">​</a></h2><p>早期的时候，<em>React</em> 官方提供了 <em>Flux</em>，<em>Flux</em> 的特点如下：</p><ul><li>单向数据流。视图事件或者外部测试用例发出 <em>Action</em> ，经由 <em>Dispatcher</em> 派发给 <em>Store</em> ，<em>Store</em> 会触发相应的方法更新数据、更新视图</li><li><strong>Store 可以有多个</strong></li><li><strong>Store 不仅存放数据，还封装了处理数据的方法</strong></li></ul><p><em>2015</em> 年的时候，<em>Dan Abramov</em> 推出的 <em>Redux</em> 席卷了整个 <em>React</em> 社区，<em>Redux</em> 本质就是在 <em>Flux</em> 上做了一些更新：</p><ul><li><p><strong>单向数据流</strong>。<em>View</em> 发出 <em>Action</em> (<code>store.dispatch(action)</code>)，<em>Store</em> 调用 <em>Reducer</em> 计算出新的 <em>state</em> ，若 <em>state</em> 产生变化，则调用监听函数重新渲染 View （<code>store.subscribe(render)</code>）</p></li><li><p><strong>单一数据源</strong>，只有一个 <em>Store</em></p></li><li><p><em>state</em> 是只读的，每次状态更新之后只能返回一个新的 <em>state</em></p></li><li><p>没有 <em>Dispatcher</em> ，而是在 <em>Store</em> 中集成了 <em>dispatch</em> 方法，<strong><code>store.dispatch()</code> 是 <em>View</em> 发出 <em>Action</em> 的唯一途径</strong></p></li><li><p>支持使用中间件（<em>Middleware</em>）管理异步数据流</p></li></ul><p><img src="https://s2.loli.net/2024/09/06/I8iO57oUyRxHvtw.png" alt=""></p><p><em>Redux</em> 官网：<em><a href="https://redux.js.org/" target="_blank" rel="noreferrer">https://redux.js.org/</a></em></p><p><em>Redux</em> 数据流：</p><p><img src="https://s2.loli.net/2024/09/06/fmwoaN1LKMZyxBD.png" alt=""></p><p><em>Redux</em> 示例：<em>ToDoList</em></p><p>在浏览器中使用 <em>redux</em> 扩展工具，首先需要打开谷歌浏览器的扩展应用商店，下载 <em>redux devtools</em></p><p><img src="https://s2.loli.net/2024/09/06/jx3s1gWbv4uAPfm.png" alt=""></p><p>接下来需要在创建 <em>store</em> 的地方，添加如下的代码：</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> store</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> createStore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    todoReducer,</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> window.__REDUX_DEVTOOLS_EXTENSION__ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> window.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">__REDUX_DEVTOOLS_EXTENSION__</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>详细可以参阅：<em><a href="https://github.com/zalmoxisus/redux-devtools-extension#usage" target="_blank" rel="noreferrer">https://github.com/zalmoxisus/redux-devtools-extension#usage</a></em></p><h2 id="react-redux-介绍-1" tabindex="-1"><em>React-redux</em> 介绍 <a class="header-anchor" href="#react-redux-介绍-1" aria-label="Permalink to &quot;*React-redux* 介绍&quot;">​</a></h2><p><em>Redux</em> 是一个独立的第三方库，之后 <em>React</em> 官方在 <em>Redux</em> 的基础上推出了 <em>React-redux</em>：<em><a href="https://react-redux.js.org/" target="_blank" rel="noreferrer">https://react-redux.js.org/</a></em></p><p>最新版的 <em>React-redux</em>，已经全面拥抱了 <em>Hooks</em>，内置了诸如：</p><ul><li><em>useSelector</em></li><li><em>useDispatch</em></li><li><em>useStore</em></li></ul><p>一类的 <em>Hook</em>，我们只要掌握这一类 <em>Hook</em>，就可以轻松上手。</p><p>另外，<em>Redux</em> 官方还推出了 <em>Redux Toolkit</em>，来简化整个 <em>Redux</em> 的使用。官方文档：<em><a href="https://redux-toolkit.js.org/" target="_blank" rel="noreferrer">https://redux-toolkit.js.org/</a></em></p><p>因此现在在 <em>React</em> 应用中，状态管理库的使用一般都是 <em>React-redux + Redux Toolkit</em></p><p><em>React-redux</em> 示例：<em>ToDoList</em></p><p><strong>和后端进行交互</strong></p><p>一般来讲，当数据发生变化时，不仅仅是前端的状态库要更新数据，服务器端也要对应的对数据进行更新，此时的更新流程如下：</p><p><img src="https://s2.loli.net/2024/09/06/sDI4yr3tqMS7HRa.png" alt=""></p><p>和后端交互示例：学生管理系统</p>`,37)])])}const c=s(r,[["render",l]]);export{h as __pageData,c as default};
